def _format_links(link_x):
    """
    Format links part
    :param link_x: list, which has several dicts in it
    :return: formatted string
    """
    try:
        pairs = ""
        for _dict in link_x:
            pairs += _dict['rel'] + '-> ' + _dict['href'] + '\n'
        return pairs[:-1]

    except Exception:
        return link_x

